/* os.cwd -- getcwd(NULL, 0) allocates a buffer sized to the
   current path. We copy into a z_t64_t and free the libc
   buffer so ownership stays uniform. On Windows it is
   GetCurrentDirectoryW's native path, as UTF-8. */
static z_t826_t z_os_cwd(void);
static z_t826_t z_os_cwd(void) {
    z_t826_t out = {0};
#if defined(_WIN32)
    char* buf = NULL;
    DWORD need = GetCurrentDirectoryW(0, NULL);
    int e = (int)GetLastError();
    if (need > 0) {
        wchar_t* w = (wchar_t*)z_xmalloc((size_t)need * sizeof(wchar_t));
        DWORD got = GetCurrentDirectoryW(need, w);
        e = (int)GetLastError();
        if (got > 0 && got < need) buf = z_win_utf8(w, (int)got, NULL);
        free(w);
    }
#else
    char* buf = getcwd(NULL, 0);
    int e = errno;
#endif
    if (buf == NULL) {
        z_t824_t* boxed = (z_t824_t*)z_xmalloc(sizeof(z_t824_t));
        *boxed = z_io_os_error(e);
        out.tag = Z_T826_TAG_0;
        out.data = boxed;
        return out;
    }
    z_t64_t* boxed = (z_t64_t*)z_xmalloc(sizeof(z_t64_t));
    *boxed = z_t64_new(buf);
    free(buf);
    out.tag = Z_T826_TAG_1;
    out.data = boxed;
    return out;
}


/* os.exePath -- absolute path of the running executable. Linux
   reads /proc/self/exe; macOS uses _NSGetExecutablePath; Windows
   GetModuleFileNameW, a native path. Copied
   into a z_t64_t so ownership stays uniform with the other os
   string natives. */
#if defined(__APPLE__)
#include <mach-o/dyld.h>
#endif
static z_t826_t z_os_exePath(void);
static z_t826_t z_os_exePath(void) {
    z_t826_t out = {0};
#if defined(_WIN32)
    /* the buffer doubles until the name fits: a long path is not cut short */
    DWORD cap = 512;
    char* path = NULL;
    for (;;) {
        wchar_t* w = (wchar_t*)z_xmalloc((size_t)cap * sizeof(wchar_t));
        DWORD got = GetModuleFileNameW(NULL, w, cap);
        if (got == 0) {
            free(w);
            break;
        }
        if (got < cap) {
            path = z_win_utf8(w, (int)got, NULL);
            free(w);
            break;
        }
        free(w);
        cap *= 2;
    }
    if (path == NULL) {
        z_t824_t* boxed = (z_t824_t*)z_xmalloc(sizeof(z_t824_t));
        *boxed = z_io_os_error((int)GetLastError());
        out.tag = Z_T826_TAG_0;
        out.data = boxed;
        return out;
    }
    z_t64_t* sb = (z_t64_t*)z_xmalloc(sizeof(z_t64_t));
    *sb = z_t64_new(path);
    free(path);
    out.tag = Z_T826_TAG_1;
    out.data = sb;
    return out;
#else
    char buf[4096];
#if defined(__APPLE__)
    uint32_t bufsize = (uint32_t)sizeof(buf);
    if (_NSGetExecutablePath(buf, &bufsize) != 0) {
        z_t824_t* boxed = (z_t824_t*)z_xmalloc(sizeof(z_t824_t));
        z_t824_t e = {0};
        e.tag = Z_T824_TAG_10;
        z_t64_t* sp = (z_t64_t*)z_xmalloc(sizeof(z_t64_t));
        *sp = z_t64_new("the executable's path is longer than 4095 bytes");
        e.data = sp;
        *boxed = e;
        out.tag = Z_T826_TAG_0;
        out.data = boxed;
        return out;
    }
#else
    ssize_t len = readlink("/proc/self/exe", buf, sizeof(buf) - 1);
    if (len < 0) {
        int e = errno;
        z_t824_t* boxed = (z_t824_t*)z_xmalloc(sizeof(z_t824_t));
        *boxed = z_io_os_error(e);
        out.tag = Z_T826_TAG_0;
        out.data = boxed;
        return out;
    }
    buf[len] = '\0';
#endif
    z_t64_t* boxed = (z_t64_t*)z_xmalloc(sizeof(z_t64_t));
    *boxed = z_t64_new(buf);
    out.tag = Z_T826_TAG_1;
    out.data = boxed;
    return out;
#endif
}


