/* z_start -- what C's `main` runs before `z_main`: the hash seed, and on
   Windows the standard streams switched to binary mode, so a program's bytes
   reach them as written -- no "\n" -> "\r\n" translation -- as on every other
   host. */
static void z_start(void) {
#if defined(_WIN32)
    _setmode(_fileno(stdin), _O_BINARY);
    _setmode(_fileno(stdout), _O_BINARY);
    _setmode(_fileno(stderr), _O_BINARY);
#endif
    z_siphash_init();
}
int main(int argc, char* argv[]) {
    z_os_argc_g = argc;
    z_os_argv_g = argv;
    z_start();
    z_main();
    return 0;
}
